// v3 (B5): optional shared-secret gate — set EXPECTED_TOKEN here AND send header x-portco-token from Clay to enable.
const EXPECTED_TOKEN = "";
const _hdrs = ($input.first().json && $input.first().json.headers) || {};
if (EXPECTED_TOKEN && String(_hdrs['x-portco-token'] || '') !== EXPECTED_TOKEN) { throw new Error('webhook auth failed: missing/wrong x-portco-token header'); }
// Build the dedup index from Claygent (only entries that already have a URL count as "known").
// No agent, no prompt — this flow discovers companies from the VC's own site.
const body = ($input.first().json && $input.first().json.body) ? $input.first().json.body : $input.first().json;
const vc_account_id = body.vc_account_id || "";
const vc_name       = body.vc_name || "";
const vc_domain     = body.vc_domain || "";
const claygent      = body.claygent_portcos;
function normalizeDomain(d){ if(!d||typeof d!=="string") return ""; return d.toLowerCase().trim().replace(/^https?:\/\//,"").replace(/^www\./,"").replace(/[\/?#].*$/,""); }
function registrableDomain(d){ const n=normalizeDomain(d); if(!n) return ""; const p=n.split("."); if(p.length<=2) return n; const last2=p.slice(-2).join("."); const COMPOUND=["co.uk","org.uk","ac.uk","gov.uk","co.kr","com.br","com.au","co.jp","co.il","co.za","co.nz","com.mx","co.in","com.sg","com.tr","com.cn","com.hk","co.th","com.tw","com.co"]; return (COMPOUND.indexOf(last2)>-1 && p.length>=3)?p.slice(-3).join("."):last2; }
function normalizeName(name){ if(!name||typeof name!=="string") return ""; let s=name.toLowerCase().trim(); s=s.replace(/[.,]?\s+(inc|llc|ltd|limited|corp|corporation|co|gmbh|sa|ag|plc|pte|bv)\.?$/i,""); return s.replace(/[^a-z0-9]/g,""); }
function parseExisting(raw){ if(!raw) return []; let arr=null; if(Array.isArray(raw)) arr=raw; else if(typeof raw==="object"&&Array.isArray(raw.portfolio_companies)) arr=raw.portfolio_companies; else if(typeof raw==="string"){ try{const p=JSON.parse(raw); arr=Array.isArray(p)?p:((p&&p.portfolio_companies)||null);}catch(e){arr=null;} } if(!arr) return []; return arr.map(function(x){ return (typeof x==="string")?{name:x,url:null}:{name:(x&&x.name)||"",url:(x&&x.url)||null}; }).filter(function(x){return x.name||x.url;}); }
const existing = parseExisting(claygent);
const knownNames = []; const knownDomains = [];
for (const p of existing){ if (!p.url) continue; const n = normalizeName(p.name); if(n) knownNames.push(n); const d = registrableDomain(p.url); if(d) knownDomains.push(d); }
return [{ json: { vc_account_id, vc_name, vc_domain, known_names: knownNames, known_domains: knownDomains } }];

function normalizeDomain(d){ if(!d||typeof d!=="string") return ""; return d.toLowerCase().trim().replace(/^https?:\/\//,"").replace(/^www\./,"").replace(/[\/?#].*$/,""); }
function registrableDomain(d){ const n=normalizeDomain(d); if(!n) return ""; const p=n.split("."); if(p.length<=2) return n; const last2=p.slice(-2).join("."); const COMPOUND=["co.uk","org.uk","ac.uk","gov.uk","co.kr","com.br","com.au","co.jp","co.il","co.za","co.nz","com.mx","co.in","com.sg","com.tr","com.cn","com.hk","co.th","com.tw","com.co"]; return (COMPOUND.indexOf(last2)>-1 && p.length>=3)?p.slice(-3).join("."):last2; }
function normalizeName(name){ if(!name||typeof name!=="string") return ""; let s=name.toLowerCase().trim(); s=s.replace(/[.,]?\s+(inc|llc|ltd|limited|corp|corporation|co|gmbh|sa|ag|plc|pte|bv)\.?$/i,""); return s.replace(/[^a-z0-9]/g,""); }
function cleanUrl(u){ if(!u||typeof u!=="string") return null; let s=u.trim(); const m=s.match(/https?:\/\/[^\s)\]]+/i); if(m) s=m[0]; if(s===""||s==="/"||s.indexOf("#")===0||/^(javascript|mailto|tel):/i.test(s)) return null; if(/^https?:\/\//i.test(s)) return /^https?:\/\/[^\/\s]+\.[a-z]{2,}/i.test(s)?s:null; return /^[^\/\s]+\.[a-z]{2,}/i.test(s)?("https://"+s):null; }
function hostOf(u){ return String(u||"").replace(/^https?:\/\//i,"").split("/")[0].toLowerCase(); }
const BLOCK = new Set(["firecrawl.dev","linkedin.com","twitter.com","x.com","facebook.com","instagram.com","threads.net","crunchbase.com","youtube.com","pitchbook.com","bloomberg.com","wikipedia.org","g2.com","github.com","medium.com","apps.apple.com","play.google.com","getro.com","getro.io","consider.com","pinpointhq.com","teamtailor.com","greenhouse.io","lever.co","ashbyhq.com","workable.com","bamboohr.com","altareturn.com"]);
const PLATFORM_SUBDOMAIN = /^(jobs|job|careers|career|apply|boards|board|talent|hire|hiring|work)\./i;
// Let an LLM pick THE portfolio-list page from the map results. Handles any slug (/companies-list,
// /portfolio, ...) and domain drift (abstract.vc -> abstract.com) that deterministic rules can't.
const cfg = $('Build config').first().json;
const resp = $input.first().json || {};
function getLinks(d,dep){ if(!d||typeof d!=="object"||dep>6) return null; if(Array.isArray(d.links)) return d.links; if(d.data&&Array.isArray(d.data.links)) return d.data.links; if(Array.isArray(d.data)) return d.data; if(Array.isArray(d)) return d; for(const k in d){ const v=d[k]; if(v&&typeof v==="object"){ const f=getLinks(v,(dep||0)+1); if(f) return f; } } return null; }
const links = getLinks(resp,0) || [];
const cands = []; const seen = new Set();
for(const l of links){
  const url = (typeof l==="string") ? l : (l && l.url) ? l.url : "";
  if(!url) continue;
  if(/\.(xml|rss|json|txt|pdf)(\?|$)/i.test(url)) continue;        // drop sitemaps/feeds
  if(seen.has(url)) continue; seen.add(url);
  cands.push({ url: url, title: (l&&l.title)||"", desc: String((l&&l.description)||"").slice(0,220) });
  if(cands.length>=400) break;
}
// v3 (B4): deterministically promote portfolio-ish slugs before truncating to 60 (map order kept within classes — stable sort)
const PRIO = /(portfolio|companies|investments|our-companies|startups|ventures)/i;
cands.sort(function(a,b){ return (PRIO.test(b.url)?1:0)-(PRIO.test(a.url)?1:0); });
const top = cands.slice(0,60);
const list = top.map((c,i)=> (i+1)+". "+c.url+"\n   title: "+c.title+"\n   desc: "+c.desc).join("\n");
const prompt =
  "Below are pages from the website of the VC firm \"" + cfg.vc_name + "\".\n\n" +
  "Identify THE single page that lists the firm's PORTFOLIO COMPANIES — the directory/index of companies they have invested in. It is NOT the team page, blog, jobs board, news, or a sitemap. Use the titles and descriptions to decide (a portfolio list usually names multiple companies). If several qualify, choose the most comprehensive one. Copy the url EXACTLY from the list. If none of these is a portfolio list, return an empty url.\n\n" +
  "Pages:\n" + list + "\n\n" +
  "Respond ONLY as compact JSON: {\"index_url\":\"<exact url from the list, or empty string>\"}";
return [{ json: { vc_account_id: cfg.vc_account_id, vc_name: cfg.vc_name, vc_domain: cfg.vc_domain, _candidate_urls: top.map(c=>c.url), _llm_prompt: prompt } }];

function normalizeDomain(d){ if(!d||typeof d!=="string") return ""; return d.toLowerCase().trim().replace(/^https?:\/\//,"").replace(/^www\./,"").replace(/[\/?#].*$/,""); }
function registrableDomain(d){ const n=normalizeDomain(d); if(!n) return ""; const p=n.split("."); if(p.length<=2) return n; const last2=p.slice(-2).join("."); const COMPOUND=["co.uk","org.uk","ac.uk","gov.uk","co.kr","com.br","com.au","co.jp","co.il","co.za","co.nz","com.mx","co.in","com.sg","com.tr","com.cn","com.hk","co.th","com.tw","com.co"]; return (COMPOUND.indexOf(last2)>-1 && p.length>=3)?p.slice(-3).join("."):last2; }
function normalizeName(name){ if(!name||typeof name!=="string") return ""; let s=name.toLowerCase().trim(); s=s.replace(/[.,]?\s+(inc|llc|ltd|limited|corp|corporation|co|gmbh|sa|ag|plc|pte|bv)\.?$/i,""); return s.replace(/[^a-z0-9]/g,""); }
function cleanUrl(u){ if(!u||typeof u!=="string") return null; let s=u.trim(); const m=s.match(/https?:\/\/[^\s)\]]+/i); if(m) s=m[0]; if(s===""||s==="/"||s.indexOf("#")===0||/^(javascript|mailto|tel):/i.test(s)) return null; if(/^https?:\/\//i.test(s)) return /^https?:\/\/[^\/\s]+\.[a-z]{2,}/i.test(s)?s:null; return /^[^\/\s]+\.[a-z]{2,}/i.test(s)?("https://"+s):null; }
function hostOf(u){ return String(u||"").replace(/^https?:\/\//i,"").split("/")[0].toLowerCase(); }
function pathOf(u){ const s=String(u||"").replace(/^https?:\/\//i,""); const i=s.indexOf("/"); return i<0?"":s.slice(i).replace(/[?#].*$/,"").replace(/\/+$/,""); }   // NEW: path after host; "" = bare root
const BLOCK = new Set(["firecrawl.dev","linkedin.com","twitter.com","x.com","facebook.com","instagram.com","threads.net","crunchbase.com","youtube.com","pitchbook.com","bloomberg.com","wikipedia.org","g2.com","github.com","medium.com","apps.apple.com","play.google.com","getro.com","getro.io","consider.com","pinpointhq.com","teamtailor.com","greenhouse.io","lever.co","ashbyhq.com","workable.com","bamboohr.com","altareturn.com"]);
const PLATFORM_SUBDOMAIN = /^(jobs|job|careers|career|apply|boards|board|talent|hire|hiring|work)\./i;
const cfg = $('Build config').first().json;
const ctx = $('Build find-index prompt').first().json;
const cands = (ctx._candidate_urls||[]).map(function(u){return String(u);});
const candSet = new Set(cands); const candNorm = new Set(cands.map(function(u){return u.replace(/\/$/,"");}));
const resp = $input.first().json || {};
function llmText(r){ r=r||{}; let c=null;
  if(r.choices&&r.choices[0]&&r.choices[0].message) c=r.choices[0].message.content;
  if(c==null&&r.message) c=(typeof r.message.content!=="undefined")?r.message.content:r.message;
  if(c==null&&typeof r.content!=="undefined") c=r.content;
  if(c==null&&typeof r.text!=="undefined") c=r.text;
  if(c==null&&typeof r.output_text!=="undefined") c=r.output_text;
  if(Array.isArray(c)) c=c.map(function(b){return (b&&(b.text||b.content))?(b.text||b.content):(typeof b==="string"?b:"");}).join(" ");
  if(c&&typeof c==="object") c=c.text||c.content||JSON.stringify(c);
  return (typeof c==="string")?c:(c!=null?String(c):""); }
const txt = llmText(resp);
let picked = "";
try{ const o=JSON.parse(txt); if(o&&typeof o.index_url==="string") picked=o.index_url.trim(); }
catch(e){ const m=txt.match(/\{[\s\S]*\}/); if(m){ try{ const o=JSON.parse(m[0]); if(o&&typeof o.index_url==="string") picked=o.index_url.trim(); }catch(e2){} } }
if(!picked){ const m2=txt.match(/https?:\/\/[^\s"')]+/i); if(m2) picked=m2[0]; }
// anti-hallucination: must be one of the candidates we showed it
if(picked && !candSet.has(picked) && !candNorm.has(picked.replace(/\/$/,""))) picked="";

if(!picked){
  // ── Single-pager fallback (2026-06-07, Footwork) ─────────────────────────────
  // Some firms (esp. seed funds on Webflow/Carrd) have NO portfolio sub-page — the
  // portfolio is listed inline on the homepage. Map then surfaces only the site root,
  // and the picker correctly won't call the homepage a "portfolio index" → empty pick.
  // Rather than quarantine, crawl the homepage and let harvest read it.
  // GATE on the single-pager signature so we DON'T auto-crawl the root of a big
  // multi-page site that simply has no portfolio page (that burns harvest credits and
  // still quarantines). Signature = map surfaced only the firm's own domain, ≤2 URLs,
  // at least one of which is the bare root. `_picker_fallback` keeps the audit trail.
  const vcReg = registrableDomain(cfg.vc_domain);
  const onVcDomain = cands.length>0 && cands.every(function(u){ return registrableDomain(u)===vcReg; });
  const rootCand = cands.find(function(u){ return registrableDomain(u)===vcReg && pathOf(u)===""; });
  if(onVcDomain && cands.length<=2 && rootCand){
    return [{ json: { vc_account_id: cfg.vc_account_id, vc_name: cfg.vc_name, vc_domain: cfg.vc_domain, index_url: rootCand, _picker_fallback: "single_page_root" } }];
  }
  // OPTIONAL — map returned nothing at all (blocked/transient). Try the homepage anyway;
  // a dead domain just self-quarantines downstream ("crawl returned no pages").
  // Delete this block if you'd rather an empty map go straight to review.
  if(cands.length===0 && vcReg){
    return [{ json: { vc_account_id: cfg.vc_account_id, vc_name: cfg.vc_name, vc_domain: cfg.vc_domain, index_url: "https://"+normalizeDomain(cfg.vc_domain), _picker_fallback: "empty_map_root" } }];
  }
  return [{ json: { vc_account_id: cfg.vc_account_id, vc_name: cfg.vc_name, vc_domain: cfg.vc_domain, index_url: "", _quarantine: true, _reason: "no portfolio-list page identified from map" } }];
}
return [{ json: { vc_account_id: cfg.vc_account_id, vc_name: cfg.vc_name, vc_domain: cfg.vc_domain, index_url: picked } }];

const c = $input.first().json;
const idx = c.index_url || (c.vc_domain ? ("https://" + String(c.vc_domain).replace(/^https?:\/\//,"")) : "(website unknown)");
const sd = $getWorkflowStaticData('global');
function memKey(dm){ return String(dm||'').toLowerCase().replace(/^https?:\/\//,'').replace(/^www\./,'').replace(/[\/?#].*$/,''); }
const mem = (sd.vc_memory || {})[memKey(c.vc_domain)] || null;
let agent_prompt =
  "VC firm: " + (c.vc_name || "(unknown)") + "\n" +
  "Firm domain: " + (c.vc_domain || "") + "\n" +
  "Portfolio page (already located for you): " + idx + "\n";
const fp = c._fingerprint || {};
if (fp.found) {
  agent_prompt += "\nAPI FINGERPRINT SCAN (deterministic pre-scan of the page source and its script bundles — verify before trusting):\n" + fp.summary + "\n";
} else {
  agent_prompt += "\nAPI FINGERPRINT SCAN: no API signatures detected in the page source" + (fp.summary ? (" (" + fp.summary + ")") : "") + ". The page may still be API-backed via runtime-loaded config.\n";
}
if (mem) {
  agent_prompt += "\nPRIOR RUN (" + (mem.ts || "?") + "): strategy=" + (mem.strategy || "?") +
    (mem.archetype ? (", archetype=" + mem.archetype) : "") +
    (mem.last_company_count ? (", last harvest count=" + mem.last_company_count) : "") +
    (mem.crawl_url ? (", crawl_url=" + mem.crawl_url) : "") +
    (mem.notes ? ("\nPrior notes: " + mem.notes) : "") +
    "\nVerify the prior approach with ONE cheap call first; if it still holds, return the SAME strategy without re-discovering — do not switch strategies for stylistic reasons; consistency across runs matters downstream. If it fails, discover from scratch.\n";
}
agent_prompt += "\nDiscover how this firm's portfolio companies are served and act per your instructions.";
return [{ json: { ...c, agent_prompt } }];

const it = $input.first().json || {};
let o = (it.output !== undefined && it.output !== null) ? it.output : it;
if (typeof o === "string") { try { o = JSON.parse(o); } catch(e){ const m = o.match(/\{[\s\S]*\}/); try { o = m ? JSON.parse(m[0]) : null; } catch(e2){ o = null; } } }
if (!o || typeof o !== "object") o = {};
const VALID = new Set(["inline","api","paginated","crawl","giant_flag","review"]);
// Parse failure / unknown strategy -> human review, NOT the harvester (giant_flag must be an explicit verdict).
let strategy = VALID.has(o.strategy) ? o.strategy : "review";
let reason = VALID.has(o.strategy) ? "" : ("unparseable/unknown strategy: " + String(o.strategy || "(missing)"));
let companies = Array.isArray(o.companies) ? o.companies.filter(function(c){ return c && typeof c === "object"; }) : [];
let page_urls = (Array.isArray(o.page_urls) ? o.page_urls : []).filter(function(u){ return typeof u === "string" && /^https?:\/\//i.test(u); });
let crawl_url = (typeof o.crawl_url === "string" && /^https?:\/\//i.test(o.crawl_url.trim())) ? o.crawl_url.trim() : "";
let truncated_pages = false;
// v3 (A1): STRATEGY-PAYLOAD COHERENCE — a valid strategy with an unusable payload must never reach an executor.
if (strategy === "crawl" && !crawl_url) { strategy = "review"; reason = "strategy=crawl but no usable crawl_url"; }
if (strategy === "paginated") {
  if (page_urls.length === 0) { strategy = "review"; reason = "strategy=paginated but no usable page_urls"; }
  else if (page_urls.length > 60) { truncated_pages = true; page_urls = page_urls.slice(0, 60); }
}
if ((strategy === "inline" || strategy === "api") && companies.length === 0) { strategy = "review"; reason = "strategy=" + String(o.strategy) + " but companies is empty"; }
// v3 (D8): implausible volume from a scraped-page strategy is a red flag (prompt-injection / runaway), not data.
if (companies.length > 500) { strategy = "review"; reason = "implausible companies count: " + companies.length + " (cap 500)"; companies = []; }
// v3.5: SELF-CONFESSED PARTIAL (Abstract case) — agent returned a 5-company sample with estimated_count 250.
// If the inline/api payload is less than HALF the agent's own estimate, it sampled: review, never a write.
// Threshold 25% (not 50%): estimated_count = TOTAL directory size BEFORE exited-exclusions (defined in
// the prompt), so honest high-exit funds (observed: 9-34% exited; allow up to ~75%) must not trip this.
// The real failure shape is extreme (5 of 250 = 2%), not borderline.
if ((strategy === "inline" || strategy === "api") && typeof o.estimated_count === "number" && o.estimated_count > 0
    && companies.length < Math.max(5, Math.ceil(o.estimated_count * 0.25))) {
  strategy = "review";
  reason = "partial " + String(o.strategy) + " payload: " + companies.length + " companies vs agent's own estimated_count " + o.estimated_count + " — sample returned as if complete";
}
// v3.19: names-only payload (text-only / Framer portfolios, e.g. Altos) — an inline/api result
// where NO company has a domain OR a lookup_url. The resolvers can act on neither, so without this every
// company drops in Parse harvest and the run is mislabeled "no_new". Route to review with an honest reason.
// (No name-search: generic names like Self / Path / Channel / SODA would mis-resolve.)
if ((strategy === "inline" || strategy === "api") && companies.length > 0) {
  var _resolvable = 0;
  for (var _i = 0; _i < companies.length; _i++) {
    var _c = companies[_i] || {};
    var _d = (typeof _c.domain === "string") ? _c.domain.trim() : "";
    var _lu = (typeof _c.lookup_url === "string") ? _c.lookup_url.trim() : "";
    if (_d || _lu) { _resolvable++; }
  }
  if (_resolvable === 0) {
    strategy = "review";
    reason = "names-only payload: " + companies.length + " companies, none with a domain or lookup_url on the page (text-only/Framer portfolio) — needs an alternate domain source; not name-searched per policy";
  }
}
return [{ json: {
  strategy: strategy,
  companies: companies,
  page_urls: page_urls,
  crawl_url: crawl_url,
  path_hint: (typeof o.path_hint === "string") ? o.path_hint.trim() : "",
  estimated_count: (typeof o.estimated_count === "number") ? o.estimated_count : null,
  _agent_archetype: o.archetype || "", _agent_notes: o.notes || "",
  _agent_escalated: !!o.escalated, _agent_confidence: o.confidence, _agent_tools: o.tools_used || [],
  _raw_strategy: o.strategy || "(missing)",
  _reason: reason,
  _page_urls_truncated: truncated_pages
} }];

const c = Array.isArray($json.companies) ? $json.companies : [];
return [{ json: { content: JSON.stringify({ companies: c }),
  _strategy: $json.strategy||"", _agent_notes: $json._agent_notes||"", _agent_tools: $json._agent_tools||[] } }];

const out = [];
for (const it of $input.all()){ const urls = Array.isArray(it.json.page_urls)?it.json.page_urls:[];
  for (const u of urls){ if (u && typeof u === "string") out.push({ json: { url: u } }); } }
return out.length ? out : [{ json: { url: "" } }];

let all = []; let failed = 0;
for (const it of $input.all()){ const j=it.json||{}; const resp=(j.body!==undefined&&j.body!==null)?j.body:j;
  const data=(resp&&resp.data)||{}; const ex=data.json||{}; const cos=Array.isArray(ex.companies)?ex.companies:[];
  if(!Array.isArray(ex.companies)) failed++;      // v3 (B2): a page that returned no extraction is a FAILURE to count, not to hide
  for (const c of cos){ if (c&&typeof c==="object") all.push(c); } }
return [{ json: { content: JSON.stringify({ companies: all }), _strategy:"paginated", _pages: $input.all().length, _failed_pages: failed } }];

// ───────────────────────────────────────────────────────────────────────────
// Parse harvest — n8n Code node ("Run Once for All Items")
// Parses the LLM-harvest output (current companies only), dedups vs known +
// within-run, then builds the resolve-prompt chunks the "Claude resolve" node
// expects. So the LLM harvest does the JUDGMENT (current vs exited/acquired) and
// resolve does the FETCH/canonicalize (rebrand/redirect + fills missing names).
//
// 2026-06-04 changes (Ethan):
//   - NAME-OPTIONAL harvest: a company may arrive with name "" (domain-only
//     listings like B Capital). Carry it through; resolve fills the name.
//   - Do NOT fall back to source_url for the domain (source_url is the VC's own
//     page -> would map to vc_domain and get dropped). Domain comes from harvest.
//   - Carry {source_url, name, domain} into each chunk as `_fallback` so
//     "Parse Claude" can fall back to the harvested domain if resolve misses
//     (no more silent drops when resolve returns empty).
//   <3 net-new -> quarantine.
// 2026-06-07 changes (Ethan): ARTICLE-LINK CASE (Footwork). A company may arrive
//   with domain "" + lookup_url=<an on-page newsletter/blog article about it>.
//   Kept as a SEPARATE "lookup" track; resolve fetches the article to recover the
//   real domain. GUARDRAILS so this NEVER loosens the already-good path:
//     * Direct entries (own-site domain) take the existing path UNCHANGED — same
//       dedup, same {source_url,name,domain} shape. lookup is only the ELSE branch
//       (fills a gap; can never override or degrade a real domain).
//     * A lookup_url is accepted ONLY if its host is in CONTENT_HOSTS (known
//       newsletter/blog platforms). News/social/other links stay dropped exactly
//       as before — the model proposes, this gate decides.
//     * Lookup dedup is by full article URL (NOT by name -> avoids generic-name
//       collisions); known-domain dedup happens post-resolve in Parse Claude.
//     * Directs are chunked FIRST, lookups after, so direct-only chunks get the
//       byte-identical original resolve prompt (extended prompt only when a chunk
//       actually contains a lookup item).
// ───────────────────────────────────────────────────────────────────────────
function normalizeDomain(d){ if(!d||typeof d!=="string") return ""; return d.toLowerCase().trim().replace(/^https?:\/\//,"").replace(/^www\./,"").replace(/[\/?#].*$/,""); }
